/* eslint-disable */
import React from 'react';
import { useEffect, useState, useRef } from "react";
import { Link } from "react-router-dom";
import "../App.css";
import { useDispatch, useSelector } from "react-redux";
import { connect } from "../redux/blockchain/blockchainActions";
import { fetchData } from "../redux/data/dataActions";
import * as s from "../styles/globalStyles";
import styled from "styled-components";
// import {CardText, CardBody, CardTitle, CardSubtitle, CardImg} from 'reactstrap';
import {nftaddress, nftmarketaddress} from "../config";
import moment from "moment";
// import Modal from 'react-bootstrap/Modal';

import { Button , Card ,Modal ,InputNumber,Form} from 'antd';
import ehtIcon from '../images/eht.png'
import amountIcon from '../images/amount.png'

//import { Header, Table, Modal } from 'semantic-ui-react';

export const StyledButton = styled.button`
  padding: 8px;
  background: ${props => props.primary ? "palevioletred" : "white"};
  color: ${props => props.primary ? "white" : "palevioletred"};

  font-size: 1em;
  margin: 1em;
  padding: 0.25em 1em;
  border: 2px solid palevioletred;
  border-radius: 3px;
`;

function Home () {
  const { Meta } = Card;
  const [confirmLoading2, setConfirmLoading2] = useState(false);

  const dispatch = useDispatch();
  const blockchain = useSelector((state) => state.blockchain);
  const data = useSelector((state) => state.data);
  const [NFTS, setNFTS] = useState([]);
  const [form1] = Form.useForm();
  const [form2] = Form.useForm();
  const [value, onChange] = useState(new Date());
  const formItemLayout = {
  	labelCol: {
  	   xs: { span: 24 },
  	   sm: { span: 8 },
  	},
  	wrapperCol: {
  	   xs: { span: 24 },
  	   sm: { span: 14 },
  	},
  };

  const [show1, setShow1] = useState(false);
  const [show2, setShow2] = useState(false);

  const handleClose1 = () => {
  	 form1.resetFields();
  	 setShow1(false);
  };
  const handleShow1 = () => setShow1(true);

  const handleClose2 = () => {
  	  form2.resetFields();
  	  setShow2(false)
  };
  const handleShow2 = () => setShow2(true);
  const [processingID, setID] = useState(0);
  const [processingPrice, setPrice] = useState(0);

  const  onChange1 = (value) => {
	inputAmount = value
  }

  const onChange2 = (value) => {
	inputPrice = value
  }

  const fetchMetaDataForNFTS = () => {
	  console.log('update',data.allTokens);
	  setNFTS([]);  
      data.allTokens.forEach((nft) => {
        fetch(nft.uri)
         .then((response) => response.json())
         .then(async (metaData) => {
			 console.log('update',nft.amount)
			 var ether_price = await blockchain.web3.utils.fromWei(nft.price,'ether');
            setNFTS((prevState) => [
              ...prevState,
              { id: nft._tradeId, tokenId: nft._tokenId, metaData: metaData, price: ether_price, amount:nft.amount, auction:nft.auction },
            ]);
          }).catch((err) => {
            console.log(err);
          });
      });  

    console.log(data.allTokens);
  };


  const buyToken = async(tradeId, price,amount) => {  
    let time = moment().format('YYYY-MM-DD HH:mm:ss'); 
	var balance = await blockchain.web3.eth.getBalance(blockchain.account);

	if(blockchain.web3.utils.fromWei(balance,'ether') > blockchain.web3.utils.fromWei(price*amount,'ether')){

    blockchain.MarketPlace.methods.buy(tradeId, time, amount)
     .send({from: blockchain.account, value: price*amount})
     .once("error", (err) => {
		alert('failed!');
      console.log(err);
     }).then(() => {
      console.log('Token sold!');
	  dispatch(fetchData(blockchain.account));
	  alert('Success!');	  
      fetchMetaDataForNFTS();
    })

    }else{
		alert("Not enough balance")
	}  



   };

   const bidToken = async(tradeId, price) => {  
    let time = moment().format('YYYY-MM-DD HH:mm:ss');
	var	wei_processPrice = await blockchain.web3.utils.toWei(processingPrice.toString(),'ether');
	var balance = await blockchain.web3.eth.getBalance(blockchain.account);
	console.log(balance);
	console.log(price);

	if(balance > price){
		console.log(ether_balance);
		console.log(ether_price);
		console.log(wei_processPrice);

		if(price > wei_processPrice){	
			blockchain.MarketPlace.methods.bid(tradeId, value.getTime(), time, price)
			.send({from: blockchain.account})
			.once("error", (err) => {
				alert('failed!');
				console.log(err);
			   }).then(() => {
				console.log('Place Bid!');
				alert('success!');	
			  })

		}else{
			alert("The price not over current highest bid ")
		}

	} else{
		alert("Not enough balance")

	}


   };


  useEffect(() => { 
    dispatch(fetchData(blockchain.account));
  }, [blockchain.MarketPlace]);
  useEffect(() => { 
    fetchMetaDataForNFTS();
  }, [data.allTokens]);


  return (
    <s.Screen>
      {blockchain.account === "" || blockchain.nft === null || blockchain.MarketPlace === null ? (
        <s.Container flex={1} ai={"center"} jc={"center"}>
          <s.TextTitle>Connect to the Blockchain</s.TextTitle>
          <s.SpacerSmall />
			 <Button
			  onClick={(e) => {
			    e.preventDefault();
			    dispatch(connect());

			  }}
			 >
			 CONNECT
			</Button>
          <s.SpacerSmall />
          {blockchain.errorMsg !== "" ? (
            <s.TextDescription>{blockchain.errorMsg}</s.TextDescription>
          ) : null}
        </s.Container>
      ) : (
       <s.Container>
       <s.flex_container> 
         {NFTS.map((nft, index) => {
            return (
			  <Link style={{textDecoration: 'none'}} to={`/detail/${nft.tokenId}/${nft.id}`}>
				 <Card
					 bodyStyle={{padding:'12px'}}
					 key={index}
				     hoverable
				     style={{ width: 240,margin:'48px 16px',borderRadius:'12px' }}
